function playPageTurnSound() {
  try {
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    const duration = 0.9;
    const createNoiseLayer = (frequency, Q, volume, delay) => {
      const bufferSize = audioContext.sampleRate * duration;
      const buffer = audioContext.createBuffer(1, bufferSize, audioContext.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const time = i / audioContext.sampleRate;
        const envelope = Math.min(time / 0.08, 1) * Math.exp(-time / 0.3);
        data[i] = (Math.random() * 2 - 1) * envelope * 0.5;
      }
      const noise = audioContext.createBufferSource();
      noise.buffer = buffer;
      const filter = audioContext.createBiquadFilter();
      filter.type = "bandpass";
      filter.frequency.value = frequency;
      filter.Q.value = Q;
      const gainNode = audioContext.createGain();
      const now = audioContext.currentTime + delay;
      gainNode.gain.setValueAtTime(0, now);
      gainNode.gain.linearRampToValueAtTime(volume * 0.08, now + 0.06);
      gainNode.gain.linearRampToValueAtTime(volume * 0.06, now + 0.12);
      gainNode.gain.exponentialRampToValueAtTime(1e-3, now + duration);
      noise.connect(filter);
      filter.connect(gainNode);
      gainNode.connect(audioContext.destination);
      noise.start(now);
      return { noise, gainNode };
    };
    createNoiseLayer(1500, 0.8, 1, 0);
    createNoiseLayer(900, 0.6, 0.6, 0.02);
    createNoiseLayer(500, 0.4, 0.4, 0.04);
  } catch (e) {
    console.error("[EME] Failed to play page turn sound:", e);
  }
}
